contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount >= c.MinSum());
        require(address(this).balance >= depositAmount);

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherBefore = address(c).balance;

        c.Collect(depositAmount); if (__ESBMC_reverted()) return;

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherAfter = address(c).balance;

        assert(balAfter == balBefore - depositAmount && etherAfter == etherBefore - depositAmount);
    }

    receive() external payable {}
}

